c.java:
class Solution {
    public int minOperations(int[] nums, int k) {
        Arrays.sort(nums);
        int lo = 0, hi = nums.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (nums[mid] < k) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

